previewCss:
.darma-loader-piano-keys {
  display: flex;
  gap: 2px;
  width: 54px;
  height: 40px;
}
.darma-loader-piano-keys i {
  width: 12px;
  height: 40px;
  border: 1px solid #c7d2fe;
  border-radius: 0 0 3px 3px;
  box-sizing: border-box;
  background: #eef2ff;
  transform-origin: top center;
  animation: darma-loader-piano-keys-press 1.2s ease-in-out infinite;
}
.darma-loader-piano-keys i:nth-child(1) { animation-delay: 0s; }
.darma-loader-piano-keys i:nth-child(2) { animation-delay: 0.15s; }
.darma-loader-piano-keys i:nth-child(3) { animation-delay: 0.3s; }
.darma-loader-piano-keys i:nth-child(4) { animation-delay: 0.45s; }
@keyframes darma-loader-piano-keys-press {
  0%, 100% { transform: rotateX(0deg); background: #eef2ff; }
  15% { transform: rotateX(-22deg); background: var(--loader-color, #6366f1); }
}

